\begin{tikzpicture}

	\begin{axis}[
	legend cell align={left},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=outer north east,
	legend style={font=\footnotesize},
	tick style={draw=none},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	axis equal,
	grid = both,
	xmin = -4.5,
	xmax = 4.5,
	ymin = -4.5,
	ymax = 4.5,
	xtick = {-10,-8,...,10},
	minor xtick = {-10,-9,...,10},
	ytick = {-10,-8,...,10},
